visual.source:
flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy<br/>デプロイを自動化" }
  EC2@{ svc: "Amazon EC2", label: "EC2" }
  ECS@{ svc: "Amazon ECS", label: "ECS" }
  L@{ svc: "AWS Lambda", label: "Lambda" }
  OP["オンプレミスのサーバー"]
  CD --> EC2 & ECS & L & OP

flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "CodeDeploy" }
  B@{ svc: "AWS Lambda", label: "BeforeAllowTraffic<br/>検証の関数" }
  A@{ svc: "AWS Lambda", label: "AfterAllowTraffic<br/>検証の関数" }
  R["結果を知らせる<br/>Succeeded か Failed<br/>1 時間返事が無ければ<br/>失敗とみなす"]
  CD -- "移す前" --> B
  CD -- "全部移した後" --> A
  B --> R
  A --> R

flowchart TB
  F["デプロイの失敗<br/>alarm のしきい値"]
  DG@{ svc: "AWS CodeDeploy", label: "deployment group<br/>自動ロールバックの設定" }
  OK@{ svc: "AWS Lambda", label: "last known good の版<br/>新しいデプロイで戻す" }
  X["ロールバック無しで<br/>手動で止めた"]
  AL@{ svc: "AWS Lambda", label: "alias が 2 つの版を指す<br/>次のデプロイが失敗" }
  F -- "条件に合う" --> DG
  DG -- "再デプロイ" --> OK
  X -. "起こりうる" .-> AL
